<?php

/**
 * @file
 * Meridian site settings (T05). Committed and owned by this repository.
 *
 * No secret lives here. The database, hash salt and trusted hosts come from the
 * platform include (Pantheon) or from the DDEV include (local). If neither
 * provides them, Drupal fails loudly: there is no hard-coded fallback.
 *
 * Include order matters. Do not reorder:
 * 1. Core defaults.
 * 2. Pantheon (scaffolded by pantheon-systems/drupal-integrations, git-ignored).
 * 3. DDEV (generated by DDEV, git-ignored).
 * 4. config_sync_directory, after the platform includes so none can override it.
 * 5. settings.local.php, last (git-ignored).
 */

// 1. Core defaults.
$databases = [];
$settings['file_scan_ignore_directories'] = [
  'node_modules',
  'bower_components',
];
$settings['entity_update_batch_size'] = 50;

// 2. Pantheon platform settings (database, hash salt, private path).
if (file_exists(__DIR__ . '/settings.pantheon.php')) {
  include __DIR__ . '/settings.pantheon.php';
}

// Do not let Drupal make sites/default read-only: Composer scaffolding writes here.
$settings['skip_permissions_hardening'] = TRUE;

// 3. DDEV.
// Automatically generated include for settings managed by ddev.
if (getenv('IS_DDEV_PROJECT') == 'true' && file_exists(__DIR__ . '/settings.ddev.php')) {
  include __DIR__ . '/settings.ddev.php';
}

// 4. Config sync directory, relative to web/: resolves to apps/drupal/config/sync.
$settings['config_sync_directory'] = '../config/sync';

// 5. Local overrides, never committed.
if (file_exists(__DIR__ . '/settings.local.php')) {
  include __DIR__ . '/settings.local.php';
}
